using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "Basic tax calculation")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    [DataRow(9.99, 1, 0.00, 9.99, DisplayName = "No tax")]
    [DataRow(50.00, 3, 1.00, 300.00, DisplayName = "Maximum tax rate (100%)")]
    [DataRow(0.01, 1, 0.05, 0.0105, DisplayName = "Small unit price with tax")]
    public void CalculateTotal_ReturnsExpectedResult(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> ApplyDiscountCases
    {
        get
        {
            yield return new object[] { 100m, 10m, 90m, "10% off 100" };
            yield return new object[] { 200m, 25m, 150m, "25% off 200" };
            yield return new object[] { 50m, 0m, 50m, "No discount" };
            yield return new object[] { 80m, 100m, 0m, "Full discount" };
            yield return new object[] { 99.99m, 50m, 49.995m, "50% off fractional price" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountCases))]
    public void ApplyDiscount_ReturnsExpectedResult(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    public static IEnumerable<object[]> ApplyDiscountInvalidCases =>
    [
        [100m, -1m],
        [100m, 101m],
    ];

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountInvalidCases))]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }
}

